import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaMars, FaVenus, FaChevronLeft, FaChevronRight } from 'react-icons/fa';
import './PetCard.css';

const PetCard = ({ pet }) => {
    const navigate = useNavigate();
    const [currentImgIndex, setCurrentImgIndex] = useState(0);

    // LOGIC: Use the 'images' list if it exists.
    // If empty, fall back to the old 'imageUrl' field.
    const images = (pet.images && pet.images.length > 0)
        ? pet.images
        : [pet.imageUrl || "https://via.placeholder.com/300?text=No+Image"];

    const nextImage = (e) => {
        e.stopPropagation(); // Prevent clicking the card itself
        setCurrentImgIndex((prev) => (prev === images.length - 1 ? 0 : prev + 1));
    };

    const prevImage = (e) => {
        e.stopPropagation();
        setCurrentImgIndex((prev) => (prev === 0 ? images.length - 1 : prev - 1));
    };

    return (
        <div className="pet-card" onClick={() => navigate(`/pet/${pet.id}`)}>
            <div className="pet-image-container">
                <img
                    src={images[currentImgIndex]}
                    alt={pet.name}
                    className="pet-image"
                />

                {/* Only show arrows if there is more than 1 image */}
                {images.length > 1 && (
                    <>
                        <button className="slider-btn left" onClick={prevImage}>
                            <FaChevronLeft />
                        </button>
                        <button className="slider-btn right" onClick={nextImage}>
                            <FaChevronRight />
                        </button>

                        {/* Little dots at the bottom */}
                        <div className="slider-dots">
                            {images.map((_, idx) => (
                                <span
                                    key={idx}
                                    className={`dot ${idx === currentImgIndex ? 'active' : ''}`}
                                />
                            ))}
                        </div>
                    </>
                )}
            </div>

            <div className="pet-info">
                <div className="pet-header">
                    <h3>{pet.name}</h3>
                    <span className="gender-icon">
                        {pet.gender === 'Male' ? <FaMars color="#3b82f6"/> : <FaVenus color="#ec4899"/>}
                    </span>
                </div>
                {/* Fallback for age if it's missing */}
                <p className="pet-breed">{pet.breed} • {pet.age || "?"} years</p>
            </div>
        </div>
    );
};

export default PetCard;
